const fs = require('node:fs');
const path = require('node:path');

const dataDir = path.resolve(__dirname, '..', 'data');
const expected = [
  ['fr03-password-reset.json', 'FR03'],
  ['fr11-order-history.json', 'FR11'],
  ['fr14-category-management.json', 'FR14'],
];

let invalid = false;

for (const [fileName, prefix] of expected) {
  const filePath = path.join(dataDir, fileName);
  const rows = JSON.parse(fs.readFileSync(filePath, 'utf8'));
  const ids = new Set();

  if (rows.length < 12) {
    console.error(`${fileName}: expected at least 12 rows, found ${rows.length}`);
    invalid = true;
  }

  for (const row of rows) {
    for (const field of ['id', 'title', 'action', 'expected', 'requirementIds']) {
      if (row[field] === undefined || row[field] === null || row[field] === '') {
        console.error(`${fileName}: ${row.id || '<unknown>'} is missing ${field}`);
        invalid = true;
      }
    }
    if (!row.id.startsWith(prefix) || ids.has(row.id)) {
      console.error(`${fileName}: invalid or duplicate id ${row.id}`);
      invalid = true;
    }
    ids.add(row.id);
  }

  console.log(`${fileName}: ${rows.length} valid data rows`);
}

if (invalid) process.exitCode = 1;

const { defineConfig, devices } = require('@playwright/test');

const studentId = process.env.STUDENT_ID || '23127272';
const runTimestamp = process.env.RUN_TIMESTAMP || new Date().toISOString();
const feature = process.env.FEATURE || 'all-features';
const browser = process.env.BROWSER || 'browser-matrix';
const reportDir = process.env.PLAYWRIGHT_HTML_OUTPUT_DIR || 'playwright-report';

module.exports = defineConfig({
  testDir: './tests',
  fullyParallel: false,
  workers: 1,
  forbidOnly: Boolean(process.env.CI),
  retries: process.env.CI ? 1 : 0,
  timeout: 30_000,
  expect: { timeout: 7_500 },
  outputDir: process.env.PLAYWRIGHT_OUTPUT_DIR || 'test-results',
  metadata: {
    'Run by': studentId,
    'Run timestamp': runTimestamp,
    Feature: feature,
    Browser: browser,
  },
  reporter: [
    ['list'],
    ['html', {
      outputFolder: reportDir,
      open: 'never',
      title: `Run by: ${studentId} | ${runTimestamp} | ${feature} | ${browser}`,
    }],
  ],
  use: {
    baseURL: process.env.ESHOP_WEB_URL || 'http://127.0.0.1:5173',
    screenshot: 'only-on-failure',
    trace: 'retain-on-failure',
    video: 'retain-on-failure',
    locale: 'vi-VN',
    timezoneId: 'Asia/Bangkok',
  },
  projects: [
    { name: 'chromium', use: { ...devices['Desktop Chrome'] } },
    { name: 'firefox', use: { ...devices['Desktop Firefox'] } },
    { name: 'webkit', use: { ...devices['Desktop Safari'] } },
  ],
});

