          PLAYWRIGHT_OUTPUT_DIR: outputDir,
        },
      },
    );

    if (result.status !== 0) failedRuns += 1;
  }
}

process.stdout.write(`\nBrowser matrix complete: ${features.length * browsers.length} runs, ${failedRuns} run(s) with failing tests.\n`);
